const input=$json.body??$json;
const s=v=>String(v??'').trim();
const first=(...v)=>v.find(x=>x!==undefined&&x!==null&&x!=='');
const leadId=s(first(input.lead_id,input.identity?.lead_id));
const propertyId=s(first(input.property_id,input.identity?.property_id));
const dealId=s(first(input.deal_id,input.identity?.deal_id));
const propertyType=s(first(input.property_type,input.property?.type)).toLowerCase();
const address=s(first(input.property_address,input.property?.address));
const id=s(first(dealId,propertyId,leadId));
const missing=[];
if(!id)missing.push('canonical_identity');
if(!propertyType)missing.push('property_type');
if(!address&&!propertyId)missing.push('property_address_or_property_id');

const direct=input.evidence??{};
const results=Array.isArray(input.evidence_results)?input.evidence_results:[];
const extracted={};
for(const r of results){
 const k=s(r.task_key);
 if(!k)continue;
 const p=r.provider_response??r.evidence??r.data??{};
 const e=p.evidence??p.packet?.evidence??p;
 if(k==='comps'&&!direct.comps)extracted.comps=e.comps??e.comps_evidence;
 if(k==='repairs'&&!direct.repairs)extracted.repairs=e.repairs??e.repair_evidence??e.estimated_repairs;
 if(k==='risk'&&!direct.property_risk&&!direct.risk_evidence)extracted.risk=e.property_risk??e.risk_evidence??e.risk;
 if(k==='buyer_demand'&&!direct.buyer_demand)extracted.buyer_demand=e.buyer_demand??e.buyer_demand_evidence;
 if(k==='exit_strategy'&&!direct.exit_strategy)extracted.exit_strategy=e.exit_strategy??e.exit_evidence;
 if(k==='valuation'&&!direct.valuation)extracted.valuation=e.valuation??e.market_value??e.arv;
}
const evidence={
 valuation:first(direct.valuation,direct.market_value,direct.arv,extracted.valuation),
 comps:first(direct.comps,direct.comps_evidence,extracted.comps),
 repairs:first(direct.repairs,direct.repair_evidence,direct.estimated_repairs,extracted.repairs),
 risk:first(direct.property_risk,direct.risk_evidence,extracted.risk),
 buyer_demand:first(direct.buyer_demand,direct.buyer_demand_evidence,extracted.buyer_demand),
 exit_strategy:first(direct.exit_strategy,direct.exit_evidence,extracted.exit_strategy)
};
const availability={
 valuation:evidence.valuation!==undefined&&evidence.valuation!==null&&evidence.valuation!=='',
 comps:Array.isArray(evidence.comps)?evidence.comps.length>0:evidence.comps!==undefined&&evidence.comps!==null&&evidence.comps!=='',
 repairs:evidence.repairs!==undefined&&evidence.repairs!==null&&evidence.repairs!=='',
 risk:evidence.risk!==undefined&&evidence.risk!==null&&evidence.risk!=='',
 buyer_demand:evidence.buyer_demand!==undefined&&evidence.buyer_demand!==null&&evidence.buyer_demand!=='',
 exit_strategy:evidence.exit_strategy!==undefined&&evidence.exit_strategy!==null&&evidence.exit_strategy!==''
};
const required=['valuation','comps','repairs','risk','buyer_demand','exit_strategy'];
const missingEvidence=required.filter(k=>!availability[k]);
const packetId=s(input.packet_id)||('underwriting-packet:'+(id||'unknown')+':v1');
const packet={
 packet_id:packetId,
 identity:{lead_id:leadId||null,property_id:propertyId||null,deal_id:dealId||null},
 property:{type:propertyType||null,address:address||null},
 evidence,
 evidence_results:results,
 evidence_quality:input.evidence_quality??input.source_quality??null,
 evidence_status:{required,available:Object.keys(availability).filter(k=>availability[k]),missing:missingEvidence,complete:missingEvidence.length===0},
 policy:{economic_viability_primary:true,reference_70pct_secondary_only:true,property_type_specific_logic:true,land_specific_logic:propertyType.includes('land')||propertyType.includes('vacant')},
 source_metadata:{request_id:s(input.request_id),evidence_version:s(input.evidence_version)||'v1',aggregated_at:new Date().toISOString(),source_workflow:s(input.source_workflow)||'wf-109'}
};
const status=missing.length?'needs_context':missingEvidence.length?'evidence_incomplete':'evidence_ready';
return[{json:{ok:missing.length===0,status,packet,missing_requirements:missing,missing_evidence:missingEvidence,orchestration:{next_action:missingEvidence.length?'collect_missing_evidence':'send_canonical_packet_to_mao_gate',next_workflow:missingEvidence.length?null:'wf-069-deal-viability-mao-strategy-gate'}}}];
